<template>
  <div class="paper-page"><header class="paper-head screen-only"><div><h1 class="page-title">组卷工作台</h1><p class="page-subtitle">高中数学 · {{dirty?'有未保存的更改':'本机草稿'}} · 原创样例题</p></div><div class="header-actions"><el-button :icon="DocumentChecked" @click="save">保存草稿</el-button><el-button type="primary" :icon="Printer" :disabled="!questions.length" @click="printOpen=true">预览与打印</el-button></div></header>
    <div v-if="basket.length" class="basket-import screen-only"><span>试题篮 <b>{{basket.length}}</b> 道题</span><el-button size="small" @click="importBasket">导入当前试卷</el-button></div>
    <div class="workbench-grid"><section class="paper-settings screen-only"><h2>试卷设置</h2><label class="field-label">试卷名称</label><el-input v-model="title" maxlength="80" aria-label="试卷名称"/><div class="settings-pair"><label><span>年级</span><el-select v-model="grade" aria-label="年级"><el-option v-for="g in ['高一','高二','高三']" :key="g" :label="g" :value="g"/></el-select></label><label><span>考试时长（分钟）</span><el-input-number v-model="duration" :min="10" :max="240" :step="10" aria-label="考试时长"/></label></div>
      <h2>自动选题条件</h2><label class="field-label">知识点范围</label><el-checkbox-group v-model="selectedChapters"><el-checkbox v-for="chapter in chapters" :key="chapter" :label="chapter" :value="chapter"/></el-checkbox-group><label class="field-label">题目场景</label><el-select v-model="scene" aria-label="场景"><el-option label="全部场景" value=""/><el-option v-for="s in demoMeta.scenes" :key="s" :label="s" :value="s"/></el-select><label class="field-label">目标难度</label><el-radio-group v-model="difficultyTarget"><el-radio-button :value="2">基础</el-radio-button><el-radio-button :value="3">适中</el-radio-button><el-radio-button :value="4">拔高</el-radio-button></el-radio-group>
      <h2>题型结构</h2><div class="structure-row structure-label"><span>题型</span><span>题数</span><span>每题分数</span></div><div class="structure-row" v-for="row in structure" :key="row.type"><span>{{row.type}}</span><el-input-number v-model="row.count" :min="0" :max="30" controls-position="right" size="small" :aria-label="row.type+'数量'"/><el-input-number v-model="row.score" :min="1" :max="30" controls-position="right" size="small" :aria-label="row.type+'分值'"/></div><div class="target-total">目标 {{totalCount}} 题 / {{totalScore}} 分</div><el-button class="generate-button" type="primary" :icon="MagicStick" @click="generate(false)">按条件生成样例卷</el-button><el-button class="parallel-button" :disabled="!questions.length" @click="generate(true)">生成不重复的平行卷</el-button><el-alert v-if="warnings.length" :title="warnings.join('；')" type="warning" :closable="false" show-icon/>
    </section><section class="paper-editor"><div class="editor-toolbar screen-only"><div><b>{{questions.length}}</b> 题 <span>/</span> <b>{{actualScore}}</b> 分</div><div class="editor-tools"><el-select v-model="order" aria-label="题目排序" size="small" @change="sortQuestions"><el-option label="手动顺序" value="manual"/><el-option label="按题型排序" value="type"/><el-option label="由易到难" value="difficulty"/></el-select><el-button size="small" :icon="Plus" @click="$router.push('/questions')">继续选题</el-button></div></div><div class="paper-sheet"><h2 class="paper-title">{{title||'未命名试卷'}}</h2><p class="paper-meta">{{grade}}数学 · 共 {{questions.length}} 题 · 满分 {{actualScore}} 分 · {{duration}} 分钟</p><div class="student-line">姓名：____________　班级：____________　学号：____________</div><article v-for="(q,i) in questions" :key="q.id" class="paper-question"><div class="question-toolbar"><b>{{i+1}}. {{q.type}} <span class="print-score">（{{q.score}} 分）</span></b><div class="question-controls screen-only"><el-input-number v-model="q.score" size="small" :min="1" :max="100" controls-position="right" :aria-label="'第'+(i+1)+'题分值'"/><el-tooltip content="上移"><el-button :icon="ArrowUp" circle text :disabled="i===0" aria-label="上移" @click="move(i,-1)"/></el-tooltip><el-tooltip content="下移"><el-button :icon="ArrowDown" circle text :disabled="i===questions.length-1" aria-label="下移" @click="move(i,1)"/></el-tooltip><el-tooltip content="换题"><el-button :icon="Refresh" circle text aria-label="换题" @click="replace(i)"/></el-tooltip><el-tooltip content="移除"><el-button :icon="Delete" circle text aria-label="移除试卷题目" @click="questions.splice(i,1)"/></el-tooltip></div></div><QuestionContent :question="q"/><div v-if="q.type==='解答题'&&answerSpace" class="answer-space"></div></article><el-empty v-if="!questions.length" description="尚未加入题目" :image-size="80"><el-button @click="$router.push('/questions')">从题库选题</el-button></el-empty>
      <section v-if="includeAnswers&&questions.length" class="answer-section"><h2>参考答案{{includeAnalysis?'与解析':''}}</h2><article v-for="(q,i) in questions" :key="q.id"><b>{{i+1}}.</b><div><div v-html="renderMath(q.answer)"></div><p v-if="includeAnalysis" v-html="renderMath(q.analysis)"></p></div></article></section>
      <section v-if="answerCard&&questions.length" class="answer-card"><h2>答题卡</h2><p>姓名：____________　班级：____________</p><div v-for="(q,i) in questions" :key="q.id" class="answer-card-row"><b>{{i+1}}.</b><span v-if="q.options?.length" class="answer-bubbles"><span v-for="(_,j) in q.options" :key="j">{{String.fromCharCode(65+j)}} <i></i></span></span><span v-else-if="q.type==='填空题'">________________________</span><div v-else class="answer-card-space"></div></div></section>
    </div></section></div>
    <el-dialog v-model="printOpen" title="预览与打印" width="min(460px,94vw)"><el-form label-position="top"><el-form-item label="纸张"><el-radio-group v-model="paperSize"><el-radio-button value="A4">A4</el-radio-button><el-radio-button value="A3">A3</el-radio-button></el-radio-group></el-form-item><el-form-item label="输出内容"><el-checkbox v-model="includeAnswers">卷末答案</el-checkbox><el-checkbox v-model="includeAnalysis" :disabled="!includeAnswers">详细解析</el-checkbox><el-checkbox v-model="answerSpace">作答留白</el-checkbox><el-checkbox v-model="answerCard">附答题卡</el-checkbox></el-form-item><el-alert type="info" :closable="false" title="浏览器打印 / PDF。Word 与可编辑公式导出尚未接入。"/></el-form><template #footer><el-button @click="printOpen=false">返回编辑</el-button><el-button type="primary" :icon="Printer" @click="printPaper">打印 / 保存 PDF</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { DocumentChecked, Printer, MagicStick, Plus, ArrowUp, ArrowDown, Refresh, Delete } from '@element-plus/icons-vue'
import { cloneQuestions, demoMeta } from '../mock'
import QuestionContent from '../components/QuestionContent.vue'
import { useWorkspace } from '../composables/workspace'
import { generateLocalPaper, normalizeType, paperScore } from '../utils/paper'
import { renderMath } from '../utils/math'
const {basket,draft,saveDraft}=useWorkspace(), existing=draft.value
const title=ref(existing?.title||'高中数学综合训练'),grade=ref(existing?.grade||'高三'),duration=ref(existing?.duration||90),scene=ref(existing?.scene||'')
const chapters=demoMeta.chapters, selectedChapters=ref(existing?.selectedChapters||[...chapters]),difficultyTarget=ref(existing?.difficultyTarget||3)
const structure=reactive(demoMeta.types.map(type=>({type,count:existing?.structure?.find(r=>normalizeType(r.type)===type)?.count??2,score:existing?.structure?.find(r=>normalizeType(r.type)===type)?.score??(type==='解答题'?10:5)})))
const questions=ref((existing?.questions||[]).map(q=>({...q,type:normalizeType(q.type),score:Number(q.score)||5}))),warnings=ref([]),dirty=ref(false),order=ref('manual'),printOpen=ref(false),paperSize=ref('A4'),includeAnswers=ref(false),includeAnalysis=ref(true),answerSpace=ref(true),answerCard=ref(false)
const totalCount=computed(()=>structure.reduce((sum,r)=>sum+(Number(r.count)||0),0)),totalScore=computed(()=>structure.reduce((sum,r)=>sum+(Number(r.count)||0)*(Number(r.score)||0),0)),actualScore=computed(()=>paperScore(questions.value))
watch([title,grade,duration,scene,selectedChapters,difficultyTarget,structure,questions],()=>dirty.value=true,{deep:true})
function importBasket(){const ids=new Set(questions.value.map(q=>q.id));const additions=basket.value.filter(q=>!ids.has(q.id));questions.value.push(...additions.map(q=>({...q,type:normalizeType(q.type),score:structure.find(r=>r.type===normalizeType(q.type))?.score||5})));ElMessage.success(`已导入 ${additions.length} 道题，重复题目已忽略`)}
async function generate(parallel){if(!title.value.trim()){ElMessage.warning('请输入试卷名称');return}if(!totalCount.value){ElMessage.warning('请至少设置一道题');return}const result=generateLocalPaper(cloneQuestions(),{chapters:selectedChapters.value,scene:scene.value,difficulty:difficultyTarget.value,structure},parallel?questions.value.map(q=>q.id):[]);warnings.value=result.warnings;if(!result.questions.length){ElMessage.warning('符合条件的题目不足，当前试卷已保留');return}if(questions.value.length){try{await ElMessageBox.confirm('生成结果将替换当前题目，尚未保存的更改会丢失。','替换当前试卷',{confirmButtonText:'替换',cancelButtonText:'取消'})}catch{return}}questions.value=result.questions;order.value='manual';ElMessage.success(`已生成 ${questions.value.length} 道样例题`)}
function move(i,delta){const j=i+delta;if(j<0||j>=questions.value.length)return;[questions.value[i],questions.value[j]]=[questions.value[j],questions.value[i]];order.value='manual'}
function replace(i){const q=questions.value[i],replacement=cloneQuestions().filter(item=>item.type===q.type&&!questions.value.some(used=>used.id===item.id)).sort((a,b)=>Math.abs(a.difficulty-q.difficulty)-Math.abs(b.difficulty-q.difficulty))[0];if(!replacement){ElMessage.info('当前题型没有可替换的样例题');return}questions.value.splice(i,1,{...replacement,score:q.score})}
function sortQuestions(){if(order.value==='type')questions.value.sort((a,b)=>demoMeta.types.indexOf(a.type)-demoMeta.types.indexOf(b.type));if(order.value==='difficulty')questions.value.sort((a,b)=>a.difficulty-b.difficulty)}
function save(){if(!title.value.trim()){ElMessage.warning('请输入试卷名称');return false}if(saveDraft({title:title.value,grade:grade.value,duration:duration.value,scene:scene.value,selectedChapters:[...selectedChapters.value],difficultyTarget:difficultyTarget.value,structure:structure.map(r=>({...r})),questions:questions.value.map(q=>({...q})),generated:!!questions.value.length,paperId:null})){dirty.value=false;ElMessage.success('草稿已保存到本机');return true}return false}
let printStyle
async function printPaper(){printOpen.value=false;await nextTick();printStyle?.remove();printStyle=document.createElement('style');printStyle.textContent=`@media print { @page { size: ${paperSize.value}; margin: 15mm; } }`;document.head.appendChild(printStyle);window.print()}
function keydown(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();save()}}
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>{printStyle?.remove();window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',beforeUnload)})
onBeforeRouteLeave(async()=>{if(!dirty.value)return true;try{await ElMessageBox.confirm('离开前保存当前试卷草稿？','尚未保存',{confirmButtonText:'保存并离开',cancelButtonText:'继续编辑'});return save()}catch{return false}})
</script>
<style scoped>
