ap:anywhere}.paper-meta{font-size:12px;text-align:center;color:var(--text-2)}.student-line{text-align:center;font-size:12px;margin:25px 0;line-height:2}.paper-question{padding:20px 0;border-top:1px solid var(--line)}.question-toolbar{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:14px;font-size:12px}.question-controls{display:flex;gap:0;align-items:center}.question-controls .el-input-number{width:77px;margin-right:5px}.question-controls .el-button+.el-button{margin:0}.question-controls .el-button{width:26px;height:28px}.print-score{font-weight:400}.answer-space{height:90px}.answer-section{border-top:1px solid var(--line);padding-top:25px}.answer-section h2,.answer-card h2{font-size:18px;text-align:center}.answer-section article{display:flex;gap:15px;line-height:1.9;font-size:13px;margin:18px 0}.answer-section article>div{min-width:0}.answer-section p{color:var(--text-2)}.answer-card{padding-top:30px}.answer-card>p{font-size:13px;text-align:center}.answer-card-row{display:flex;gap:20px;padding:20px 0;border-bottom:1px solid var(--line);font-size:13px;flex-wrap:wrap}.answer-bubbles{display:flex;gap:20px}.answer-bubbles>span{display:flex;gap:5px;align-items:center}.answer-bubbles i{width:15px;height:10px;border:1px solid #222;display:inline-block}.answer-card-space{width:100%;height:160px}@media(max-width:1150px){.workbench-grid{grid-template-columns:260px minmax(0,1fr);gap:18px}.paper-settings{padding-right:16px}.paper-sheet{padding:24px}}@media(max-width:900px){.workbench-grid{grid-template-columns:1fr}.paper-settings{border:0;padding:0 0 24px;border-bottom:1px solid var(--line)}.paper-settings .el-checkbox-group{grid-template-columns:1fr 1fr}.structure-row{grid-template-columns:1fr 1fr 1fr}.paper-head{align-items:flex-start;flex-wrap:wrap}}@media(max-width:500px){.paper-sheet{padding:18px}.paper-settings .el-checkbox-group{grid-template-columns:1fr}.editor-toolbar{flex-wrap:wrap}.question-toolbar{flex-wrap:wrap}.student-line{text-align:left}.paper-title{font-size:18px}}
@media print{.screen-only{display:none!important}.workbench-grid{display:block}.paper-sheet{border:0;padding:0;min-height:0}.paper-question{break-inside:avoid;border:0;padding:12px 0}.answer-section,.answer-card{break-before:page}.answer-card-row{break-inside:avoid}.paper-title{font-size:20pt}.paper-meta,.student-line{color:#000}.paper-question :deep(.q-stem){font-size:11pt}.paper-question :deep(img){max-height:45mm;object-fit:contain;object-position:left}.answer-space{height:30mm}}
</style>
